"""model covariance matrix"""from argparse import Namespaceimport torch.nn as nnimport torchfrom .mpn import MPNfrom chemprop.nn_utils import get_activation_function, initialize_weights, get_cc_dropout_hyperfrom chemprop.models.concrete_dropout import ConcreteDropout, RegularizationAccumulatorclass Downstream_Model(nn.Module):    def __init__(self, input_dim, output_dim, layers_numbers):        super(Downstream_Model, self).__init__()        self.layers_numbers = layers_numbers        self.hidden = TimeDistributed_wrapper(nn.Linear(input_dim, 256))  # hidden layer        self.hidden_2 = TimeDistributed_wrapper(nn.Linear(256, 256))        self.hidden_3 = TimeDistributed_wrapper(nn.Linear(256, 256))        self.hidden_4 = TimeDistributed_wrapper(nn.Linear(256, 256))        self.hidden_5 = TimeDistributed_wrapper(nn.Linear(256, 256))        # self.predict = torch.nn.Linear(n_hidden, n_output)   # output layer        self.predict = TimeDistributed_wrapper(nn.Linear(256, output_dim))  # output layer        self.sigma = TimeDistributed_wrapper(nn.Linear(256, output_dim))        self.drop = nn.Dropout(0.2)    def forward(self, hid):        x = self.hidden(hid)        x = self.hidden_2(x).relu()        x = self.hidden_3(x).relu()        x = self.hidden_4(x).relu()        x = self.hidden_5(x).relu()        x = self.drop(x)        mean = self.predict(x)        return meanclass MoleculeModel(nn.Module):    """A MoleculeModel is a model which contains a message passing network following by feed-forward layers."""    def __init__(self, classification: bool, multiclass: bool, aleatoric: bool, epistemic: str,                 fp_method: str, atomic_unc: bool, twoUnitOutput: bool, intensive_property: bool,                 covariance_matrix_pred: bool, covariance_matrix_save_path: str = None, output_dim=1):        """        Initializes the MoleculeModel.        :param classification: Whether the model is a classification model.        """        super(MoleculeModel, self).__init__()        self.classification = classification        self.layers_numbers = 10        # self.uq_cnn = TimeDistributed_wrapper(nn.Linear(1, 300))        # self.uq_model = Uq_Model(input_dim=300, output_dim=12, layers_numbers=self.layers_numbers)        self.downstream = Downstream_Model(input_dim=300, output_dim=output_dim, layers_numbers=self.layers_numbers)        if self.classification:            self.sigmoid = nn.Sigmoid()        self.multiclass = multiclass        if self.multiclass:            self.multiclass_softmax = nn.Softmax(dim=2)        assert not (self.classification and self.multiclass)        self.aleatoric = aleatoric        self.epistemic = epistemic        self.mc_dropout = self.epistemic == 'mc_dropout'        self.fp_method = fp_method        self.atomic_unc = atomic_unc        self.twoUnitOutput = twoUnitOutput        self.intensive_property = intensive_property        self.covariance_matrix_pred = covariance_matrix_pred        self.covariance_matrix_save_path = covariance_matrix_save_path    def create_encoder(self, args: Namespace):        self.encoder = MPN(args)    def create_ffn(self, args: Namespace):        """        Creates the feed-forward network for the model.        :param args: Arguments.        """        self.max_atom_size = args.max_atom_size        self.ffn_hidden_size = args.ffn_hidden_size        self.multiclass = args.dataset_type == 'multiclass'        if self.multiclass:            self.num_classes = args.multiclass_num_classes        if args.features_only:            first_linear_dim = args.features_size        else:            first_linear_dim = args.hidden_size  # default = 300            if args.use_input_features:  # default = false                first_linear_dim += args.features_dim        dropout = nn.Dropout(0.2)        activation = get_activation_function(args.activation)        wd, dd = get_cc_dropout_hyper(args.train_data_size, args.regularization_scale)        # Create FFN layers ['molecular', 'atomic']        if self.fp_method == 'molecular':            if args.ffn_num_layers == 1:                ffn = [                    dropout,                ]                last_linear_dim = first_linear_dim            else:                ffn = [                    dropout,                    ConcreteDropout(layer=nn.Linear(first_linear_dim, args.ffn_hidden_size),                                    reg_acc=args.reg_acc, weight_regularizer=wd,                                    dropout_regularizer=dd) if self.mc_dropout else                    nn.Linear(first_linear_dim, args.ffn_hidden_size)                ]                for _ in range(args.ffn_num_layers - 2):                    ffn.extend([                        activation,                        dropout,                        ConcreteDropout(layer=nn.Linear(args.ffn_hidden_size, args.ffn_hidden_size),                                        reg_acc=args.reg_acc, weight_regularizer=wd,                                        dropout_regularizer=dd) if self.mc_dropout else                        nn.Linear(args.ffn_hidden_size, args.ffn_hidden_size)                    ])                ffn.extend([                    activation,                    dropout,                ])                last_linear_dim = args.ffn_hidden_size            # Create FFN model            self._ffn = nn.Sequential(*ffn)            if self.aleatoric:                self.output_layer = nn.Linear(last_linear_dim, args.output_size)                self.logvar_layer = nn.Linear(last_linear_dim, args.output_size)            else:                self.output_layer = nn.Linear(last_linear_dim, args.output_size)        else:  # atomic, hybrid_dim0, hybrid_dim1            if args.fp_method == 'hybrid_dim1':                first_linear_dim = first_linear_dim * 2            if args.ffn_num_layers == 1:                ffn = [                    TimeDistributed_wrapper(dropout),                ]                last_linear_dim = first_linear_dim            else:  # ffn_num_layers default=2                ffn_mean_func = [                    TimeDistributed_wrapper(dropout),                    TimeDistributed_wrapper(                        ConcreteDropout(layer=nn.Linear(first_linear_dim, args.ffn_hidden_size),                                        reg_acc=args.reg_acc, weight_regularizer=wd,                                        dropout_regularizer=dd) if self.mc_dropout else                        nn.Linear(first_linear_dim, args.ffn_hidden_size, bias=False)                    )                ]                for _ in range(args.ffn_num_layers - 2):                    ffn_mean_func.extend([                        TimeDistributed_wrapper(activation),                        TimeDistributed_wrapper(dropout),                        TimeDistributed_wrapper(                            ConcreteDropout(layer=nn.Linear(first_linear_dim, args.ffn_hidden_size),                                            reg_acc=args.reg_acc, weight_regularizer=wd,                                            dropout_regularizer=dd) if self.mc_dropout else                            nn.Linear(first_linear_dim, args.ffn_hidden_size, bias=False)                        ),                    ])                ffn_mean_func.extend([                    TimeDistributed_wrapper(activation),                    TimeDistributed_wrapper(dropout),                ])                last_linear_dim = args.ffn_hidden_size            # Create FFN model            self._ffn = nn.Sequential(*ffn_mean_func)    def split_y_var(self, y_var_vector):        output = torch.unsqueeze(y_var_vector[:, :, 0], 2)        var = torch.unsqueeze(y_var_vector[:, :, 1], 2)        return output, var    def call_scaler(self, args):        """ pred covariance matrix need scaler """        self.scaling_factor = args.scaler_stds        print(f'scaling factor = {self.scaling_factor}')    def forward(self, *input):        hid_vec, n_atoms, uq_out, uq, a_scope, b_scope = self.encoder(*input)        hid_vec = self._ffn(hid_vec)        hid = self.downstream(hid_vec)        hid = hid.sum(1) / torch.tensor(a_scope, device='cuda')[:, 1].reshape(-1, 1)        hid = nn.Sigmoid()(hid)        return hid, uq, n_atoms, uq_out, a_scope, b_scopedef build_model(args: Namespace, scaler=None) -> nn.Module:    output_size = args.num_tasks    args.output_size = output_size    if args.dataset_type == 'multiclass':        args.output_size *= args.multiclass_num_classes    if args.epistemic == 'mc_dropout':        args.reg_acc = RegularizationAccumulator()    # for old model without this argument when it was training.    try:        args.covariance_matrix_save_path    except:        args.covariance_matrix_save_path = None    model = MoleculeModel(classification=args.dataset_type == 'classification',                          multiclass=args.dataset_type == 'multiclass', aleatoric=args.aleatoric,                          epistemic=args.epistemic, fp_method=args.fp_method, atomic_unc=args.atomic_unc,                          twoUnitOutput=args.twoUnitOutput, intensive_property=args.intensive_property,                          covariance_matrix_pred=args.covariance_matrix_pred,                          covariance_matrix_save_path=args.covariance_matrix_save_path, output_dim=args.num_tasks)    if args.covariance_matrix_pred:        model.call_scaler(args)    model.create_encoder(args)    model.create_ffn(args)    initialize_weights(model)    if args.epistemic == 'mc_dropout':        args.reg_acc.initialize(cuda=args.cuda)    return modelclass LambdaLayer(nn.Module):    def __init__(self, lambda_function):        super(LambdaLayer, self).__init__()        self.lambda_function = lambda_function    def forward(self, x):        return self.lambda_function(x)class TimeDistributed_wrapper(nn.Module):    def __init__(self, module, batch_first=False):        super(TimeDistributed_wrapper, self).__init__()        self.module = module        self.batch_first = batch_first    def forward(self, x):        if len(x.size()) <= 2:            return self.module(x)        # Squash samples and timesteps into a single axis        x_shape = x.shape        x = x.reshape(-1, x.size(-1))  # (samples * timesteps, input_size)        y = self.module(x)        y = y.reshape(x_shape[:-1] + torch.Size([y.shape[-1]]))        return y